import { ICurrencySettings, IFormatTimePrecisionElementLocale } from '@game-studio/utilities';
import { ISubGameSessionInfo } from '@game-studio/server-comms';

export interface ISessionStatus {
    AlertFrequency: number;
    CurrentBet: number;
    CurrentTime: number;
    FunBonusConversionFailed: boolean;
    LimitApproaching: boolean;
    MaxBet: number;
    MaxTime: number;
    NetBalance: number;
    SessionEnded: boolean;
    GameInProgress?: boolean;
    SessionEndTime: number;
    SessionId: number;
    SessionRestriction: number;
    TotalWinnings: number;
}

export interface ISessionSettings {
    ValidAlertFrequencies: number[];
    ValidMaxBets: number[];
    ValidMaxBetPercentages: number[];
    ValidMaxTimes: number[];
    ValidSessionRestrictions: number[];
}

export interface IPlayerData {
    EndBalance: number;
    FreePlayBalance: number;
    PreStakeBalance: number;
    PreviousStake: number;
    StartBalance: number;
    Username: string;
}

export interface ISessionManagementConfig {
    crossCheck: number;
    userId: number;
    translations: ISessionManagementTranslations;
    minStake: number;
    currency: ICurrencySettings;
    sessionEndedWindow: number;
    debugSessionValues: boolean;
    defaultSessionModel?: ISessionModel;
    freePlayBalance: number,
    subGameName: string;
    createSessionUrl: string;
}

export interface ISessionManagementLink {
    linkText: string;
    linkAddress: string;
}

export interface ISessionManagementFormTranslations {
    close: string;
    heading: string;
    infoText: string;
    confirmButton: string;
    sessionEndedRecently?: Array<string | ISessionManagementLink>;
    freePlay: {
        infoText: string;
    }
}

export interface ISessionManagementConfirmationTranslations extends ISessionManagementFormTranslations {
    modifyButton: string;
}

export interface ISessionManagementFieldsTranslations {
    maxTime: string;
    maxBet: string;
    alertFrequency: string;
    sessionRestriction: string;
    selectText: string;
    errorText: string;
    freePlay: {
        singular: string;
        plural: string;
        balanceText: string;
        sessionRestriction: string;
    }
}

export interface ISessionManagementHelpTranslations {
    help: string;
    close: string;
    maxTime: string;
    maxBet: string;
    alertFrequency: string;
    sessionRestriction: string;
    freePlay: string;
}

export interface ISessionManagementProgressTranslations {
    close: string;
    heading: string;
    amount: string;
    time: string;
    accept: string;
}

export interface ISessionManagementSessionEndedReasonsTranslations {
    heading: string;
    spent: string;
    prizes: string;
    balance: string;
}

export interface ISessionManagementSessionEndedTranslations {
    close: string;
    timeExpired: ISessionManagementSessionEndedReasonsTranslations;
    balanceExpired: ISessionManagementSessionEndedReasonsTranslations;
}

export interface ISessionManagementRestrictionTranslations {
    close: string;
    heading: string;
    info: string;
    expires: string;
    reminder: Array<string | ISessionManagementLink>;
}

export interface ISessionManagementDurations {
    second: IFormatTimePrecisionElementLocale;
    minute: IFormatTimePrecisionElementLocale;
    hour: IFormatTimePrecisionElementLocale;
    day: IFormatTimePrecisionElementLocale;
    week: IFormatTimePrecisionElementLocale;
    month: IFormatTimePrecisionElementLocale;
    year: IFormatTimePrecisionElementLocale;
    unlimited: string;
}

export interface ISessionStatusBar {
    totalSpend: string;
    totalWinnings: string;
    sessionBalance: string;
}

export interface ISessionManagementTranslations {
    form: ISessionManagementFormTranslations;
    confirmation: ISessionManagementConfirmationTranslations;
    progress: ISessionManagementProgressTranslations;
    limitApproaching: ISessionManagementProgressTranslations;
    sessionEnded: ISessionManagementSessionEndedTranslations;
    sessionRestriction: ISessionManagementRestrictionTranslations;
    fields: ISessionManagementFieldsTranslations;
    help: ISessionManagementHelpTranslations;
    durations: ISessionManagementDurations;
    statusBar: ISessionStatusBar;
}

export interface ISessionManagementStringKeyPair {
    string: string;
    value: string | number;
}

export interface ISessionModel {
    [key: string]: number;
    maxTime: number;
    maxBet: number;
    alertFrequency: number;
    sessionRestriction: number;
    freePlayBalance: number
}

export interface IUpdateSessionManagementObject {
    SessionStatus: Partial<ISessionStatus>;
    SessionSettings: Partial<ISessionSettings>;
    PlayerData: Partial<IPlayerData>;
}

export interface ISessionManagementEvents {
    'session:create': (sessionModel: ISessionModel) => void;
    'session:form:show': (response?: ISubGameSessionInfo) => void;
    'session:form:hide': () => void;
    'session:alert': () => void;
    'session:ended': () => void;
    'session:reset': () => void;
    'session:closed': () => void;
    'session:ended:closed': () => void;
}
